// รับคำขอจากบอร์ด: {cmd:"face"|"item", request_id, image_url}
const p = msg.payload || {};
if (!p.request_id || !p.image_url || (p.cmd !== "face" && p.cmd !== "item")) {
    node.warn("คำขอไม่ครบ: " + JSON.stringify(p));
    return null;
}
const busy = global.get("pending");
if (busy && Date.now() - busy.at < 10000) {
    node.warn("ยังมีงานค้าง " + busy.request_id + " ข้ามคำขอ " + p.request_id);
    return null;
}
const r2g = {
    request_id: p.request_id,
    cmd: p.cmd,
    round_id: p.request_id.replace(/-\d+$/, ""),   // request_id = round_id + "-" + ลำดับ
    at: Date.now()
};
global.set("pending", r2g);
node.status({fill: "blue", shape: "dot", text: p.cmd + " " + p.request_id});

// ถ้า CiRA ไม่ตอบใน 8 วิ ส่งไปทาง timeout (ออกทางขาที่ 2)
setTimeout(() => {
    const cur = global.get("pending");
    if (cur && cur.request_id === r2g.request_id) {
        node.send([null, {r2g: cur, payload: "timeout"}]);
    }
}, 8000);

msg.r2g = r2g;
msg.url = p.image_url;
return [msg, null];

// ภาพต้องเป็น JPEG ที่สมบูรณ์
const b = msg.payload;
if (msg.statusCode !== 200 || !Buffer.isBuffer(b) || b.length < 1000 || b[0] !== 0xFF || b[1] !== 0xD8) {
    node.warn("ดึงภาพไม่สำเร็จ status=" + msg.statusCode);
    return [null, msg];
}
global.set("lastImage", b);
msg.filename = "/data/r2g/" + msg.r2g.cmd + ".jpg";   // = F:\477\R2G\face.jpg หรือ item.jpg
return [msg, null];

// สั่ง CiRA ให้อ่านไฟล์ที่เพิ่งบันทึก
const cfg = global.get("cfg") || {};
const pend = global.get("pending");
if (pend && pend.request_id === msg.r2g.request_id) {
    pend.sentAt = Date.now();
    global.set("pending", pend);
}
// โหมดสำรอง: ไม่มีโมเดลใบหน้า → ตอบผลใบหน้าแทน CiRA ทันที
if (msg.r2g.cmd === "face" && cfg.FIXED_FACE) {
    msg.topic = "cpe477-peerach/ai/face/res";
    msg.payload = {model: "face", best: {label: cfg.FIXED_FACE, score: 1}, counts: {}, fixed: true};
    return msg;
}
msg.topic = "cpe477-peerach/ai/" + msg.r2g.cmd + "/req";
msg.payload = {request_id: msg.r2g.request_id};
return msg;

// ===== ตั้งค่าโหมดสำรอง (แก้ตรงนี้ที่เดียว แล้ว Deploy) =====
global.set("cfg", {
    // ยังไม่มีโมเดลใบหน้า: ใส่ face_label ของคนที่จะใช้สาธิต เช่น "Somchai"
    // ระบบจะข้าม CiRA ตอนสแกนหน้า แล้วใช้ชื่อนี้เลย · เว้นว่าง "" = ใช้ AI จริง
    FIXED_FACE: "",

    // CiRA ใช้ Auto Run วนตรวจตลอด (ยังทำตัวกั้นไม่ได้): ตั้ง 1500
    // จะทิ้งผล AI ที่มาเร็วกว่า 1.5 วิหลังสั่ง (อาจเป็นผลของภาพเก่า) · 0 = ปิด
    MIN_FRESH_MS: 0
});
node.status({fill:"green", shape:"dot", text: JSON.stringify(global.get("cfg"))});
return null;

// ผลใบหน้าจาก CiRA: {model, counts, best:{label, score}}
const pend = global.get("pending");
if (!pend || pend.cmd !== "face") return null;
const cfg_ = global.get("cfg") || {};
if (pend && cfg_.MIN_FRESH_MS && !(msg.payload && msg.payload.fixed) && (!pend.sentAt || Date.now() - pend.sentAt < cfg_.MIN_FRESH_MS)) {
    return null;   // ผลมาเร็วเกินไป อาจเป็นผลของภาพเก่า รอรอบถัดไป
}
      // ผลที่ไม่ได้รอ ทิ้ง
const ai = msg.payload || {};
const best = ai.best || {};
msg.r2g = pend;
msg.ai = ai;
const MIN = 0.70;                                    // ความมั่นใจขั้นต่ำของใบหน้า
if (!best.label || !(best.score >= MIN)) {
    msg.result = {request_id: pend.request_id, name: "unknown"};
    return [null, msg];
}
msg.params = [best.label];
return [msg, null];

// สร้างผลให้บอร์ด: name, employee_id, required[]
const pend = msg.r2g;
const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!rows.length) {                                   // จำหน้าได้ แต่ไม่มีงานวันนี้
    msg.result = {request_id: pend.request_id, name: "unknown"};
    node.warn("ไม่มีงานวันนี้ของ " + msg.params[0]);
    return msg;
}
const job = rows[0].job_id;                           // ถ้ามีหลายงาน ใช้งานแรก
const mine = rows.filter(r => r.job_id === job);
const jobs = global.get("roundJobs") || {};
jobs[pend.round_id] = {job_id: job, status: mine[0].status, at: Date.now()};
global.set("roundJobs", jobs);
msg.result = {
    request_id: pend.request_id,
    employee_id: mine[0].employee_code,
    name: mine[0].name,
    job_id: job,
    required: mine.map(r => ({label: r.cira_label, qty: r.qty}))
};
return msg;

// ผลของ 1 ชิ้นจาก CiRA: ตอนนี้ใช้ชนิดเดียว (best) และแนบ counts ไปด้วย
const pend = global.get("pending");
if (!pend || pend.cmd !== "item") return null;
const cfg_ = global.get("cfg") || {};
if (pend && cfg_.MIN_FRESH_MS && (!pend.sentAt || Date.now() - pend.sentAt < cfg_.MIN_FRESH_MS)) {
    return null;   // ผลมาเร็วเกินไป อาจเป็นผลของภาพเก่า รอรอบถัดไป
}

const ai = msg.payload || {};
const best = ai.best || {};
msg.r2g = pend;
msg.ai = ai;
msg.result = {request_id: pend.request_id, label: best.label || "", counts: ai.counts || {}};
return msg;

// CiRA ไม่ตอบ หรือดึงภาพไม่ได้ → ตอบบอร์ดให้ลองใหม่
const pend = msg.r2g || global.get("pending");
if (!pend) return null;
msg.r2g = pend;
msg.ai = {error: "timeout"};
msg.result = pend.cmd === "face"
    ? {request_id: pend.request_id, name: "unknown"}
    : {request_id: pend.request_id, label: "", counts: {}};
return msg;

// ส่งผลเฉพาะคำขอที่กำลังรอ แล้วล้างงานค้าง
const cur = global.get("pending");
if (!cur || !msg.result || cur.request_id !== msg.result.request_id) return null;
global.set("pending", null);
const ai = msg.ai || {};
const best = ai.best || {};
const out = {topic: "cpe477-peerach/result", payload: msg.result};
const log = {params: [
    cur.request_id, cur.round_id, cur.cmd,
    msg.result.label !== undefined ? msg.result.label : (msg.result.name || ""),
    best.score || null,
    JSON.stringify(ai.counts || {}),
    cur.cmd === "item" ? global.get("lastImage") : null     // ไม่เก็บภาพใบหน้า (PDPA)
]};
node.status({fill: "green", shape: "dot", text: JSON.stringify(msg.result).slice(0, 60)});
return [out, log];

