// บอร์ดส่ง: {round_id, employee_id, name, items:[{label, qty}]}
const p = msg.payload || {};
if (!p.round_id || !Array.isArray(p.items)) return null;
const jobs = global.get("roundJobs") || {};
const j = jobs[p.round_id];
if (!j) node.warn("ไม่รู้งานของรอบ " + p.round_id + " (Node-RED อาจรีสตาร์ท) บันทึกแบบไม่มี job");
msg.round_id = p.round_id;
msg.params = [
    p.round_id,
    p.employee_id || "",
    j ? j.job_id : null,
    j && j.status === "out" ? "return" : "out",
    !!j,
    JSON.stringify(p.items)
];
return msg;

// บันทึกสำเร็จ (หรือเคยบันทึกแล้ว) → ตอบ saved บอร์ดจะหยุดส่งซ้ำ
const jobs = global.get("roundJobs") || {};
delete jobs[msg.round_id];
global.set("roundJobs", jobs);
msg.topic = "cpe477-peerach/saved";
msg.payload = {round_id: msg.round_id, saved: true};
return msg;

// แปลงคำสั่งจากหน้าเว็บเป็นคำสั่ง SQL
const p = msg.payload || {};
const LOAD = "SELECT json_build_object(\n 'workers', (SELECT coalesce(json_agg(x ORDER BY x.id), '[]'::json) FROM\n             (SELECT id, employee_code, name, face_label, active FROM workers) x),\n 'tools',   (SELECT coalesce(json_agg(x ORDER BY x.id), '[]'::json) FROM\n             (SELECT id, name, cira_label, active FROM tools) x),\n 'jobs',    (SELECT coalesce(json_agg(x ORDER BY x.job_date, x.id), '[]'::json) FROM\n             (SELECT j.id, to_char(j.job_date, 'YYYY-MM-DD') AS job_date, j.title, j.status, w.name AS worker,\n                     (SELECT string_agg(t.cira_label || ' x' || jt.qty, ', ' ORDER BY t.id)\n                        FROM job_tools jt JOIN tools t ON t.id = jt.tool_id WHERE jt.job_id = j.id) AS tools\n                FROM jobs j JOIN workers w ON w.id = j.worker_id\n               WHERE j.job_date >= CURRENT_DATE) x),\n 'rounds',  (SELECT coalesce(json_agg(x), '[]'::json) FROM\n             (SELECT r.round_id, to_char(r.saved_at, 'YYYY-MM-DD HH24:MI') AS saved_at, w.name AS worker,\n                     r.direction, r.complete,\n                     (SELECT count(*) FROM scans s WHERE s.round_id = r.round_id AND s.kind = 'item' AND s.image IS NOT NULL) AS photos,\n                     (SELECT string_agg(t.cira_label || ' ' || ri.got || '/' || ri.need, ', ' ORDER BY t.id)\n                        FROM round_items ri JOIN tools t ON t.id = ri.tool_id WHERE ri.round_id = r.round_id) AS items\n                FROM rounds r LEFT JOIN workers w ON w.id = r.worker_id\n               ORDER BY r.saved_at DESC LIMIT 30) x)\n) AS data;";
const out = { action: p.action, params: [] };
switch (p.action) {
case "load":
    out.query = LOAD;
    break;
case "create_job": {
    const items = (p.items || []).filter(i => Number(i.qty) > 0);
    if (!p.worker_id || !p.job_date || !p.title || !items.length) { node.warn("ข้อมูลงานไม่ครบ"); return null; }
    out.query = "WITH j AS (INSERT INTO jobs(job_date, worker_id, title) VALUES ($1::date, $2, $3) RETURNING id) " +
                "INSERT INTO job_tools(job_id, tool_id, qty) SELECT j.id, (x->>'tool_id')::int, (x->>'qty')::int " +
                "FROM j, jsonb_array_elements($4::jsonb) AS x";
    out.params = [p.job_date, p.worker_id, p.title, JSON.stringify(items)];
    out.done = "สร้างงานแล้ว";
    break; }
case "delete_job":
    out.query = "WITH d AS (DELETE FROM job_tools WHERE job_id = $1 AND EXISTS (SELECT 1 FROM jobs WHERE id = $1 AND status = 'assigned')) " +
                "DELETE FROM jobs WHERE id = $1 AND status = 'assigned'";
    out.params = [p.job_id];
    out.done = "ลบงานแล้ว";
    break;
case "reset_job":
    out.query = "UPDATE jobs SET status = 'assigned' WHERE id = $1";
    out.params = [p.job_id];
    out.done = "ตั้งงานกลับเป็นยังไม่รับของแล้ว";
    break;
case "add_worker":
    if (!p.employee_code || !p.name || !p.face_label) return null;
    out.query = "INSERT INTO workers(employee_code, name, face_label) VALUES ($1, $2, $3)";
    out.params = [p.employee_code, p.name, p.face_label];
    out.done = "เพิ่มพนักงาน " + p.name + " แล้ว";
    break;
case "toggle_worker":
    out.query = "UPDATE workers SET active = NOT COALESCE(active, true) WHERE id = $1";
    out.params = [p.id];
    out.done = "เปลี่ยนสถานะพนักงานแล้ว";
    break;
case "add_tool":
    if (!p.name || !p.cira_label) return null;
    out.query = "INSERT INTO tools(name, cira_label) VALUES ($1, $2)";
    out.params = [p.name, p.cira_label];
    out.done = "เพิ่มเครื่องมือ " + p.name + " แล้ว";
    break;
case "toggle_tool":
    out.query = "UPDATE tools SET active = NOT COALESCE(active, true) WHERE id = $1";
    out.params = [p.id];
    out.done = "เปลี่ยนสถานะเครื่องมือแล้ว";
    break;
case "photos":   // รูปของที่สแกนในรอบนี้ (ไม่มีรูปใบหน้า)
    if (!p.round_id) return null;
    out.query = "SELECT json_build_object('photos_for', $1::text, 'photos', coalesce(json_agg(x ORDER BY x.created_at), '[]'::json)) AS data FROM " +
                "(SELECT label, score, to_char(created_at, 'HH24:MI:SS') AS t, created_at, encode(image, 'base64') AS img " +
                " FROM scans WHERE round_id = $1 AND kind = 'item' AND image IS NOT NULL) x";
    out.params = [p.round_id];
    out._client = msg._client;   // ส่งรูปกลับเฉพาะเครื่องที่กดดู
    break;
default:
    return null;
}
return out;

// load → ส่งข้อมูลให้ทุกหน้า · คำสั่งอื่น → แจ้งผลแล้วโหลดใหม่
if (msg.action === "photos") {
    const row = Array.isArray(msg.payload) ? msg.payload[0] : null;
    return [{ payload: row ? row.data : { photos: [] }, _client: msg._client }, null, null];
}
if (msg.action === "load") {
    const row = Array.isArray(msg.payload) ? msg.payload[0] : null;
    return [{ payload: row ? row.data : {} }, null, null];
}
return [null, { payload: msg.done || "บันทึกแล้ว" }, { payload: { action: "load" } }];

// แปลง error จากฐานข้อมูลเป็นข้อความที่อ่านง่าย
const e = (msg.error && msg.error.message) || "";
let t = "บันทึกไม่สำเร็จ: " + e;
if (/duplicate key/i.test(e)) t = "ข้อมูลซ้ำกับที่มีอยู่แล้ว (รหัส / face_label / cira_label ต้องไม่ซ้ำ)";
else if (/foreign key/i.test(e)) t = "ลบไม่ได้ เพราะมีข้อมูลอื่นอ้างถึงอยู่";
else if (/ECONN|timeout|getaddrinfo/i.test(e)) t = "ต่อฐานข้อมูลไม่ได้ (เช็ก Tailscale และคอมเครื่องที่มีฐานข้อมูล)";
return { payload: t };
